package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name  string
		text  string
		width int
		want  []string
	}{
		{
			name:  "nil for zero width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil for negative width",
			text:  "hello world",
			width: -1,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word shorter than width",
			text:  "hello",
			width: 10,
			want:  []string{"hello"},
		},
		{
			name:  "single word equal to width",
			text:  "hello",
			width: 5,
			want:  []string{"hello"},
		},
		{
			name:  "single word longer than width",
			text:  "superlongword",
			width: 5,
			want:  []string{"superlongword"},
		},
		{
			name:  "simple wrap",
			text:  "hello world foo",
			width: 10,
			want:  []string{"hello", "world foo"},
		},
		{
			name:  "multiple lines",
			text:  "one two three four five",
			width: 8,
			want:  []string{"one two", "three", "four five"},
		},
		{
			name:  "collapse whitespace",
			text:  "hello    world",
			width: 10,
			want:  []string{"hello world"},
		},
		{
			name:  "no trailing or leading spaces",
			text: "  hello world  ",
			width: 20,
			want: []string{"hello world"},
		},
		{
			name:  "exact fit",
			text:  "hello world",
			width: 11,
			want:  []string{"hello world"},
		},
		{
			name:  "must break",
			text:  "hello world",
			width: 6,
			want:  []string{"hello", "world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && tt.want == nil {
				return
			}
			if len(tt.want) == 0 && got == nil {
				return
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %d lines, want %d: %v", len(got), len(tt.want), got)
			}
			for i := range got {
				if got[i] != tt.want[i] {
					t.Errorf("line %d: got %q, want %q", i, got[i], tt.want[i])
				}
				if len(got[i]) > tt.width {
					t.Errorf("line %d length %d exceeds width %d", i, len(got[i]), tt.width)
				}
				if len(got[i]) > 0 && (got[i][0] == ' ' || got[i][len(got[i])-1] == ' ') {
					t.Errorf("line %q has leading/trailing space", got[i])
				}
			}
		})
	}
}

